const j = $('When Called').first().json || {};
const cfg = $('Load Config').first().json || {};

// SAFETY SWITCH: only liveMode === true (boolean) in UXR Config allows real sends. False, missing, a string, anything else = test mode.
const liveMode = cfg.liveMode === true;
const forcedTest = !liveMode;
const testMode = forcedTest || j.test_mode === true || j.test_mode === 'true';
const testRecipient = String(cfg.testRecipient || 'g.andreini@gmail.com');
const testMax = Number(cfg.testMaxRecipients) || 3;

const batchId = (j.batch_id || '').toString().trim();
const body = (j.email_body || cfg.emailBody || '').toString();
const subject = (j.email_subject || cfg.emailSubject || 'Invitation: Help us improve n8n').toString();
const calendly = (j.calendly_url || '').toString().trim();

let error = null;
if (!batchId) error = 'Missing batch_id.';
else if (!body) error = 'Missing email_body.';
else if (body.indexOf('{{calendly_link}}') !== -1 && !calendly) error = 'The email body contains {{calendly_link}} but no calendly_url was provided. Refusing to send.';
else if (testMode && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(testRecipient)) error = 'Test mode is on but testRecipient in UXR Config is not a valid email. Refusing to send.';

return [{ json: {
  valid: !error, error,
  batch_id: batchId, email_subject: subject, email_body: body, calendly_url: calendly,
  test_mode: testMode, forced_test: forcedTest, live_mode: liveMode,
  test_recipient: testRecipient, test_max: testMax,
  from_email: String(cfg.fromEmail || 'n8n Research <noreply@info.n8n.io>'),
  reply_to: String(cfg.replyTo || 'design@n8n.io'),
  cooldown_field: String(cfg.cooldownField || 'last_user_research_invite_date'),
  cooldown_days: Number(cfg.cooldownDays) || 60
} }];

const v = $('Validate Send').first().json;
const staged = $('Get Staged Candidates').all().map(i => i.json).filter(r => r && r.email);
// Cooldown evidence: rows sent (status sent) plus rows booked. Two reads, one per status (the Data Table node cannot OR reliably).
const recentRows = $('Get Recently Sent').all().map(i => i.json).concat($input.all().map(i => i.json)).filter(r => r && r.email && (r.status === 'sent' || r.status === 'booked'));

// DUPLICATE GUARD 1: emails already invited within the cooldown window, from the Candidates table.
// Covers the gap before the Customer.io cooldown segment refreshes and rows that were sent but not stamped.
// A booked row without sent_at (booked through a shared/test link) counts from booked_at; a row with no usable date is ignored, not blocked forever.
const cutoff = Date.now() - (Number(v.cooldown_days) || 60) * 24 * 60 * 60 * 1000;
const recentlySent = new Set();
for (const r of recentRows) {
  const t = r.sent_at ? Date.parse(r.sent_at) : (r.booked_at ? Date.parse(r.booked_at) : NaN);
  if (Number.isFinite(t) && t >= cutoff) recentlySent.add(String(r.email).trim().toLowerCase());
}

// DUPLICATE GUARD 2: the same email twice inside this batch (two Customer.io profiles sharing an address).
const seen = new Set();
const items = [];
for (const r of staged) {
  const key = String(r.email).trim().toLowerCase();
  let attrs = {};
  try { attrs = JSON.parse(r.attributes_json || '{}'); } catch (e) { attrs = {}; }
  if (!attrs || typeof attrs !== 'object') attrs = {};
  const cioId = attrs.cio_id || attrs.id || '';
  const base = { row_id: r.id, email: r.email, cio_id: cioId, test_mode: v.test_mode === true, from_email: v.from_email, reply_to: v.reply_to, cooldown_field: v.cooldown_field };
  // Exactly one mailbox per row: 'a@x.com,b@y.com' would reach SMTP as two recipients
  if (!/^[^@\s,;<>]+@[^@\s,;<>]+\.[^@\s,;<>]+$/.test(key)) { items.push({ ...base, skip: true, skip_reason: 'invalid email address' }); continue; }
  if (recentlySent.has(key)) { items.push({ ...base, skip: true, skip_reason: 'already invited within the last ' + v.cooldown_days + ' days (Candidates table)' }); continue; }
  if (seen.has(key)) { items.push({ ...base, skip: true, skip_reason: 'same email appears twice in this batch' }); continue; }
  seen.add(key);
  items.push({ ...base, skip: false });
}

// Test mode: cap the real sends, but keep skipped rows so they get marked
let toSend = items.filter(i => !i.skip);
const skipped = items.filter(i => i.skip);
if (v.test_mode === true) toSend = toSend.slice(0, v.test_max);
if (toSend.length === 0 && skipped.length === 0) return [{ json: { __none: true, batch_id: v.batch_id } }];

const out = toSend.map(i => {
  const r = staged.find(s => s.id === i.row_id) || {};
  let body = v.email_body || '';
  body = body.split('{{first_name}}').join(r.first_name || 'there');
  body = body.split('{{calendly_link}}').join(v.calendly_url || '');
  let subject = v.email_subject;
  let recipient = i.email;
  if (v.test_mode === true) {
    // TEST MODE: the real person never receives anything; the test inbox gets it with a header saying who it was for
    recipient = v.test_recipient;
    subject = '[TEST for ' + i.email + '] ' + subject;
    body = 'TEST MODE (UXR Recruiting). This invite would have gone to: ' + i.email + '\nBatch: ' + v.batch_id + '\nNo Customer.io stamp was written.\n-----\n\n' + body;
  }
  return { json: { ...i, recipient, subject, body } };
});
return out.concat(skipped.map(i => ({ json: i })));

const rows = $input.all().map(i => i.json).filter(r => r && r.email);
const sent = rows.filter(r => r.status === 'sent' || r.status === 'test_sent').length;
const failed = rows.filter(r => r.status === 'failed').length;
const skipped = rows.filter(r => r.status === 'skipped_duplicate').length;
const details = rows.map(r => ({ email: r.email, status: r.status }));
const v = $('Validate Send').first().json;
// Stamp problems are collected from Record Result (the rows themselves only carry the status)
let stampFailed = 0;
try { stampFailed = $('Record Result').all().map(i => i.json).filter(r => r && r.stamp_failed === true).length; } catch (e) { stampFailed = 0; }
const testNote = v.test_mode ? ' TEST MODE: every email was redirected to ' + v.test_recipient + ' (max ' + v.test_max + '), no Customer.io stamping.' : '';
const dupNote = skipped ? ' ' + skipped + ' duplicate(s) skipped (already invited within ' + v.cooldown_days + ' days or repeated in the batch).' : '';
const stampNote = stampFailed ? ' ' + stampFailed + ' email(s) sent but not stamped on Customer.io (cooldown covered by the Candidates table only).' : '';
return [{ json: { success: failed === 0, sent, failed, skipped_duplicate: skipped, stamp_failed: stampFailed, test_mode: v.test_mode === true, test_recipient: v.test_mode ? v.test_recipient : null, batch_id: v.batch_id, details, message: 'Sent ' + sent + ', failed ' + failed + '.' + dupNote + stampNote + testNote } }];

const sent = $input.first().json || {};
const item = $('Send Loop').first().json;
const ok = !sent.error;
return [{ json: { ...item, send_ok: ok, stamp_skipped: !item.cio_id, error: sent.error ? (typeof sent.error === 'string' ? sent.error : (sent.error.message || JSON.stringify(sent.error).slice(0, 200))) : null } }];

const item = $('Send Loop').first().json;
const inp = $input.first().json || {};

// Duplicate path: no email was sent, mark the row so nobody retries it
if (item.skip === true) {
  return [{ json: { row_id: item.row_id, email: item.email, final_status: 'skipped_duplicate', error: item.skip_reason || 'duplicate', sent_at: '' } }];
}

const chk = $('Check Send OK').first().json;
const emailOk = chk.send_ok === true;
let err = chk.error || null;
let stampFailed = false;
const stampRan = emailOk && chk.test_mode !== true && !chk.stamp_skipped;
// The stamp ran (live mode, cio_id present): an HTTP >= 400 or a transport error (no statusCode, error set) both mean not stamped
if (stampRan && inp.statusCode !== undefined && inp.statusCode >= 400) {
  stampFailed = true;
  err = 'Email sent but Customer.io stamp failed (HTTP ' + inp.statusCode + '): cooldown relies on the Candidates table for this person';
} else if (stampRan && inp.error) {
  stampFailed = true;
  err = 'Email sent but Customer.io stamp failed (' + (typeof inp.error === 'string' ? inp.error : (inp.error.message || 'transport error')) + '): cooldown relies on the Candidates table for this person';
}
if (emailOk && chk.test_mode !== true && chk.stamp_skipped) {
  stampFailed = true;
  err = 'Email sent but NOT stamped: no cio_id on the candidate row';
}
// The truth of the row is whether the person received the email: a failed stamp must not reopen them to another batch
const finalStatus = emailOk ? (chk.test_mode === true ? 'test_sent' : 'sent') : 'failed';
return [{ json: { row_id: chk.row_id, email: chk.email, final_status: finalStatus, stamp_failed: stampFailed, error: err, sent_at: emailOk ? new Date().toISOString() : '' } }];
